```index.html
<!DOCTYPE html>
<html>
<head>
<style>
    body { margin: 0; overflow: hidden; background: #222; text-align: center; font-family: sans-serif; color: white; }
    #ball { width: 50px; height: 50px; background: red; border-radius: 50%; position: absolute; cursor: pointer; }
    #score { font-size: 24px; margin-top: 20px; }
</style>
</head>
<body>
    <div id="score">Punkte: 0</div>
    <div id="ball"></div>

    <script>
        let score = 0;
        let x = 100, y = 100;
        let dx = 5, dy = 5;
        const ball = document.getElementById('ball');
        const scoreDisplay = document.getElementById('score');

        function move() {
            x += dx; y += dy;
            if (x < 0 || x > window.innerWidth - 50) dx *= -1;
            if (y < 0 || y > window.innerHeight - 50) dy *= -1;
            ball.style.left = x + 'px';
            ball.style.top = y + 'px';
            requestAnimationFrame(move);
        }

        ball.addEventListener('click', () => {
            score++;
            scoreDisplay.innerText = 'Punkte: ' + score;
            dx *= 1.1; dy *= 1.1;
        });

        move();
    </script>
</body>
</html>
